def components(grid, color):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=color or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append(comp)
    return out

def transform(grid):
    h,w=len(grid),len(grid[0])
    if any(len(row)!=w for row in grid): raise ValueError('ragged grid')
    bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors=set(v for row in grid for v in row if v!=bg)
    # Border-attached L shape supplies the color used for the selected object.
    guides=[]
    for color in colors:
        for comp in components(grid,color):
            cells=set(comp)
            if not any(r in (0,h-1) or c in (0,w-1) for r,c in comp): continue
            for r,c in comp:
                nr=sum((r,x) in cells for x in range(w)); nc=sum((y,c) in cells for y in range(h))
                if nr>=2 and nc>=2: guides.append((nr*nc,color))
    if not guides: return [row[:] for row in grid]
    guide=max(guides)[1]
    # A singleton of a color marks the separated, same-color multi-cell patch
    # positioned diagonally down-left; recolor that patch to the guide color.
    for marker in sorted(colors-{guide}):
        groups=components(grid,marker)
        singles=[p for comp in groups if len(comp)==1 for p in comp]
        patches=[comp for comp in groups if len(comp)>1]
        options=[]
        for sr,sc in singles:
            for comp in patches:
                cy=sum(r for r,c in comp)/len(comp); cx=sum(c for r,c in comp)/len(comp)
                if cy>sr and cx<sc:
                    d=min((r-sr)**2+(c-sc)**2 for r,c in comp)
                    options.append((d,-len(comp),comp))
        if options:
            target=min(options,key=lambda z:(z[0],z[1]))[2]
            out=[row[:] for row in grid]
            for r,c in target: out[r][c]=guide
            return out
    return [row[:] for row in grid]

